SHEET_DATA_PYTH["Расшифровка"].literals["B4"] = "Энергия 2 — «двойка» в пифагорейской психоматрице выступает показателем жизненной энергии человека.";
SHEET_DATA_PYTH["Расшифровка"].formulas["C4"] = function(SHEET, cell, rangeVals) { return cell("Расчет", "F36"); };
