SHEET_DATA_PYTH["Расшифровка"].literals["B19"] = "Духовность и материальность - отвечает за гармонию между либеральными и духовными аспектами человека";
SHEET_DATA_PYTH["Расшифровка"].formulas["C19"] = function(SHEET, cell, rangeVals) { return cell("Расчет", "B28"); };
