SHEET_DATA_PYTH["Расшифровка"].literals["B27"] = "Благоприятные возможности";
SHEET_DATA_PYTH["Расшифровка"].formulas["C27"] = function(SHEET, cell, rangeVals) { return cell("Matr", "BE10"); };
